import pandas as pd
from typing import Dict

def run(inputs: Dict[str, pd.DataFrame]) -> Dict[str, pd.DataFrame]:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"]["high_ts"].iloc[0]

    # Filter events by watermark
    events_to_apply = cdc_events[cdc_events["event_ts"] <= watermark].copy()

    # Sort events by (item_id, event_ts, event_seq) to apply in order
    events_to_apply = events_to_apply.sort_values(
        by=["item_id", "event_ts", "event_seq"],
        ignore_index=True
    )

    # Initialize working state from target_snapshot
    # Use a dict for easier manipulation: item_id -> {qty_on_hand, last_event_ts}
    state = {}
    for _, row in target_snapshot.iterrows():
        state[row["item_id"]] = {
            "qty_on_hand": row["qty_on_hand"],
            "last_event_ts": row["last_event_ts"]
        }

    # Apply each event sequentially
    for _, event in events_to_apply.iterrows():
        item_id = event["item_id"]
        event_ts = event["event_ts"]
        op = event["op"]
        qty = event["qty"]

        if op == "R":  # Receipt: add to qty_on_hand
            if item_id not in state:
                state[item_id] = {"qty_on_hand": 0, "last_event_ts": event_ts}
            state[item_id]["qty_on_hand"] += qty
            state[item_id]["last_event_ts"] = event_ts

        elif op == "A":  # Adjustment: set absolute qty
            # Note: If item was deleted, it re-creates starting from the absolute qty
            state[item_id] = {"qty_on_hand": qty, "last_event_ts": event_ts}

        elif op == "D":  # Delist: remove item
            if item_id in state:
                del state[item_id]

    # Convert state back to DataFrame
    result_rows = []
    for item_id, item_state in state.items():
        result_rows.append({
            "item_id": item_id,
            "qty_on_hand": item_state["qty_on_hand"],
            "last_event_ts": item_state["last_event_ts"]
        })

    if result_rows:
        new_snapshot = pd.DataFrame(result_rows)
        # Ensure consistent column types
        new_snapshot["item_id"] = new_snapshot["item_id"].astype("int64")
        new_snapshot["qty_on_hand"] = new_snapshot["qty_on_hand"].astype("float64")
        new_snapshot["last_event_ts"] = pd.to_datetime(new_snapshot["last_event_ts"], utc=False)
    else:
        new_snapshot = pd.DataFrame(columns=["item_id", "qty_on_hand", "last_event_ts"])
        new_snapshot["item_id"] = new_snapshot["item_id"].astype("int64")
        new_snapshot["qty_on_hand"] = new_snapshot["qty_on_hand"].astype("float64")
        new_snapshot["last_event_ts"] = pd.to_datetime(new_snapshot["last_event_ts"], utc=False)

    return {"new_snapshot": new_snapshot}
